removed_parallel_block:
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (n = 0; n < NG; n = n + 1)
            gq[n] <= {QW{1'b0}};
    end
    else begin
        // 衰减【每样本一次】（sample_en 门控）：
        //   第一版漏了 sample_en，于是每时钟衰减一次 = 快 512 倍
        //   （实测滑音速率 14046/样本，而 step=10 应该是 28/样本）。
        //   关滑音时也要照常走完，否则残留偏移会永久卡住。
        if (sample_en) begin
            for (n = 0; n < NG; n = n + 1) begin
                if (gq[n] > 0)
                    gq[n] <= (gq[n] > stp)  ? (gq[n] - stp)  : {QW{1'b0}};
                else if (gq[n] < 0)
                    gq[n] <= (gq[n] < nstp) ? (gq[n] - nstp) : {QW{1'b0}};
                else
                    gq[n] <= {QW{1'b0}};
            end
        end

        // 滑音初值装载（优先级最高：与 inc/amp/gate 同一个消费拍）
        if (gw_en === 1'b1)
            gq[gw_note] <= gw_val;
    end
end
